// Delivery pacing: one run every 30 minutes enqueues at most 30 candidates and
// sends at most 25 messages (about 50 per hour). Each send verifies Stripe and
// calls Resend (about one second), so a run needs roughly 45 seconds. The tick
// deadline is the preview budget plus the delivery budget, so a building
// preview cannot squeeze delivery into a deadline error.

func NewCheckoutRecoveryWorker(transport ResendTransport, verify RecoveryPaymentVerifier) *CheckoutRecoveryWorker {
	return &CheckoutRecoveryWorker{Owner: ulid.Make().String(), Transport: transport, Verify: verify, MaxPerRun: recoveryMaxSendPerRun}
}

func recoveryDeliveryRunConsumed(err error) bool {
	return err == nil || errors.Is(err, context.DeadlineExceeded)
}

// checkoutRecoveryManualStripeWindow is the single predicate chain for manual
// Stripe attempts in a preview window; the raw page and the count share it so
// they cannot drift apart.

func CountCheckoutRecoveryManualStripeContext(ctx context.Context, asOf, startAt time.Time) (int64, error) {
	var count int64
	err := checkoutRecoveryManualStripeWindow(ctx, asOf, startAt).Count(&count).Error
	return count, err
}

